def bisection(f, a, b, tol):
    n = 0
    while (b - a) / 2 > tol:
        c = (a + b) / 2
        if f(a) * f(c) < 0:
            b = c
        else:
            a = c
        n += 1
    return (a + b) / 2, n

f = lambda x: x**3 - x - 2
kok, adim = bisection(f, 1.0, 2.0, 1e-3)
print(adim, round(kok, 4))

def f(x):
    return x*x - 3

def df(x):
    return 2*x

x = 2.0
for _ in range(2):
    x = x - f(x) / df(x)
print(round(x, 6))

def lagrange(xs, ys, x):
    total = 0.0
    for i in range(len(xs)):
        term = ys[i]
        for j in range(len(xs)):
            if i != j:
                term *= (x - xs[j]) / (xs[i] - xs[j])
        total += term
    return total

print(round(lagrange([1, 2, 4], [1, 4, 16], 3), 6))
